/**
 * The command-line interface of `test10.py`:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=int, required=True)   # ... through '--e'
 */

import { ArgumentParser } from './argparse.mjs';
import { pyInt } from '../python/int.mjs';

/**
 * argparse takes `prog` from the program name. The reference build reports
 * `test10_executable`, so usage/error output stays byte-identical to it.
 */
export const PROG = 'test10_executable';

export const ARGUMENT_NAMES = ['a', 'b', 'c', 'd', 'e'];

export function buildParser(prog = PROG) {
  const parser = new ArgumentParser({ prog });
  for (const name of ARGUMENT_NAMES) {
    parser.addArgument([`--${name}`], { type: pyInt, required: true });
  }
  return parser;
}

/** Parse `argv` (already stripped of the node/script entries) into `{a, b, c, d, e}`. */
export function parseArgs(argv, prog = PROG) {
  return buildParser(prog).parseArgs(argv);
}

/**
 * A focused re-implementation of CPython 3.12's `argparse`, covering the surface the
 * ported script uses: long options with a `type` converter, `required`, and the
 * automatic `-h/--help`. It reproduces argparse's message wording, usage/help
 * layout, error precedence and exit codes.
 *
 * Deliberately unsupported: positional arguments, nargs other than 0 or 1,
 * subparsers, groups. The parser being ported declares none of them.
 */

import { reprStr } from '../python/repr.mjs';

/** Raised for an error attributable to one action; rendered as "argument --x: ...". */
export class ArgumentError extends Error {
  constructor(action, message) {
    super(`argument ${action.optionStrings[0]}: ${message}`);
  }
}

/**
 * Thrown instead of calling `process.exit`, so buffered stdout/stderr writes are
 * flushed before the process ends (`process.exit` can truncate a piped stdout).
 */
export class ParserExit extends Error {
  constructor(status) {
    super(`parser exit ${status}`);
    this.status = status;
  }
}

/** argparse's `_negative_number_matcher`; Python's `\d` is the Unicode Nd category. */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this._actions = [];
    this._optionStringActions = new Map();
    this.addArgument(['-h', '--help'], { action: 'help', help: 'show this help message and exit' });
  }

  addArgument(optionStrings, { action = 'store', type = null, required = false, metavar = null, help = null } = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^-+/, '').replace(/-/g, '_');
    const entry = {
      optionStrings,
      dest,
      action,
      type,
      required,
      // argparse defaults an optional's metavar to the upper-cased dest.
      metavar: metavar ?? dest.toUpperCase(),
      help,
      nargs: action === 'help' ? 0 : 1,
    };
    this._actions.push(entry);
    for (const optionString of optionStrings) this._optionStringActions.set(optionString, entry);
    return entry;
  }

  // ---------------------------------------------------------------- formatting

  _invocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
  }

  formatUsage() {
    const parts = this._actions.map((action) => {
      const invocation =
        action.nargs === 0 ? action.optionStrings[0] : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog}${parts.length ? ' ' : ''}${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this._actions.map((action) => this._invocation(action));
    // argparse aligns help text at min(longest invocation + indent + 2, 24).
    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT.length));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    const lines = [this.formatUsage(), '\n', 'options:\n'];
    this._actions.forEach((action, index) => {
      const header = `${INDENT}${invocations[index]}`;
      if (action.help === null) {
        lines.push(`${header}\n`);
      } else if (header.length + 2 <= helpPosition) {
        lines.push(`${header.padEnd(helpPosition)}${action.help}\n`);
      } else {
        lines.push(`${header}\n${' '.repeat(helpPosition)}${action.help}\n`);
      }
    });
    return `${lines.join('').replace(/^\n+|\n+$/g, '')}\n`;
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** argparse's `error()`: usage plus one message on stderr, exit status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new ParserExit(2);
  }

  // ------------------------------------------------------------------ parsing

  /**
   * argparse's `_parse_optional`. Returns null when the token is a positional,
   * `[action, optionString, explicitArg]` for a recognised option, or
   * `[null, token, null]` for something option-shaped but unknown.
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (argString[0] !== '-') return null;

    const exact = this._optionStringActions.get(argString);
    if (exact !== undefined) return [exact, argString, null];
    if (argString.length === 1) return null;

    const separator = argString.indexOf('=');
    if (separator !== -1) {
      const optionString = argString.slice(0, separator);
      const known = this._optionStringActions.get(optionString);
      if (known !== undefined) return [known, optionString, argString.slice(separator + 1)];
    }

    const candidates = this._getOptionTuples(argString);
    if (candidates.length > 1) {
      const matches = candidates.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (candidates.length === 1) return candidates[0];

    // Looks like a negative number, and no option string does: treat as a value.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;
    return [null, argString, null];
  }

  /** argparse's `_get_option_tuples`: abbreviated long options and bundled short ones. */
  _getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      const separator = argString.indexOf('=');
      const prefix = separator === -1 ? argString : argString.slice(0, separator);
      const explicitArg = separator === -1 ? null : argString.slice(separator + 1);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(prefix)) result.push([action, optionString, explicitArg]);
      }
    } else {
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString === shortPrefix) result.push([action, optionString, shortExplicitArg]);
        else if (optionString.startsWith(argString)) result.push([action, optionString, null]);
      }
    }
    return result;
  }

  parseKnownArgs(argStrings) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (action.action === 'store') namespace[action.dest] = undefined;
    }

    // Classify every token up front, as argparse does: 'O' for option, 'A' for a
    // value/positional, '-' for the end-of-options separator.
    const pattern = [];
    const optionTuples = new Map();
    let afterSeparator = false;
    argStrings.forEach((argString, index) => {
      if (!afterSeparator && argString === '--') {
        afterSeparator = true;
        pattern.push('-');
        return;
      }
      if (afterSeparator) {
        pattern.push('A');
        return;
      }
      const tuple = this._parseOptional(argString);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, tuple);
        pattern.push('O');
      }
    });

    const extras = [];
    const seen = new Set();

    const takeAction = (action, argument) => {
      seen.add(action);
      if (action.action === 'help') {
        this.printHelp();
        throw new ParserExit(0);
      }
      namespace[action.dest] = this._getValue(action, argument);
    };

    let index = 0;
    while (index < argStrings.length) {
      const tuple = optionTuples.get(index);
      if (tuple === undefined) {
        // No positionals are declared, so every non-option token is left over.
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }
      const [action, , explicitArg] = tuple;
      if (action === null) {
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }
      if (explicitArg !== null) {
        if (action.nargs === 0) {
          throw new ArgumentError(action, `ignored explicit argument ${reprStr(explicitArg)}`);
        }
        takeAction(action, explicitArg);
        index += 1;
        continue;
      }
      if (action.nargs === 0) {
        takeAction(action, null);
        index += 1;
        continue;
      }
      if (pattern[index + 1] !== 'A') {
        throw new ArgumentError(action, 'expected one argument');
      }
      takeAction(action, argStrings[index + 1]);
      index += 2;
    }

    // Missing required options are reported before leftover tokens are.
    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    let namespace;
    let extras;
    try {
      [namespace, extras] = this.parseKnownArgs(argStrings);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** argparse's `_get_value`: run the converter, reporting failures per action. */
  _getValue(action, argString) {
    if (action.type === null) return argString;
    try {
      return action.type(argString);
    } catch {
      const typeName = action.type.pyName ?? action.type.name;
      throw new ArgumentError(action, `invalid ${typeName} value: ${reprStr(argString)}`);
    }
  }
}

/**
 * CPython's `int(str)` coercion.
 *
 * Accepts surrounding Unicode whitespace, an optional sign, Unicode decimal digits
 * (not just ASCII) and PEP 515 underscore separators between digits. Values are
 * arbitrary precision, so the result is a BigInt.
 */

/** Code points for which Python's Py_UNICODE_ISSPACE is true. */
const WHITESPACE = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680,
    0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009,
    0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  ],
);

/** Raised for input `int()` would reject; the caller turns it into an argparse error. */
export class PyValueError extends Error {}

const DECIMAL_DIGIT = /\p{Nd}/u;
const INT_LITERAL = /^([+-]?)(\p{Nd}+(?:_\p{Nd}+)*)$/u;

function isSpace(ch) {
  return WHITESPACE.has(ch.codePointAt(0));
}

function strip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isSpace(chars[start])) start += 1;
  while (end > start && isSpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

/**
 * Numeric value of a Unicode decimal digit. Unicode guarantees decimal digits come
 * in contiguous runs of ten starting at the script's zero, so walking backwards to
 * the first non-digit code point recovers the offset within the run.
 */
function decimalValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  for (let back = 1; back <= 10 && cp - back >= 0; back += 1) {
    if (!DECIMAL_DIGIT.test(String.fromCodePoint(cp - back))) return back - 1;
  }
  return 0;
}

export function pyInt(text) {
  const match = INT_LITERAL.exec(strip(text));
  if (match === null) throw new PyValueError(`invalid literal for int() with base 10: ${text}`);

  const [, sign, body] = match;
  let ascii = '';
  for (const ch of body) {
    if (ch !== '_') ascii += String(decimalValue(ch));
  }
  return BigInt(sign === '-' ? `-${ascii}` : ascii);
}

/** `int.__name__`, used verbatim in argparse's "invalid int value" message. */
pyInt.pyName = 'int';

/**
 * CPython `repr()` / `print()` rendering for the value shapes this port produces.
 *
 * The mapping between JS and Python values is deliberate and load-bearing:
 *   BigInt  -> Python int    (node ids are arbitrary precision, so they must not be Numbers)
 *   Number  -> Python float  (edge weights and path lengths)
 *   Boolean -> Python bool
 *   Array   -> Python list
 *   PyTuple -> Python tuple
 */

/** Marker wrapper so `(1, 2)` can be told apart from the list `[1, 2]`. */
export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export function tuple(...items) {
  return new PyTuple(items);
}

/** repr() of a str: single quotes, switching to double quotes when the text contains `'`. */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (ch === quote) out += '\\' + ch;
    else {
      const cp = ch.codePointAt(0);
      if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
      else out += ch;
    }
  }
  return out + quote;
}

/** Shortest decimal digits that round-trip, plus the exponent of the leading digit. */
function shortestDigits(x) {
  if (x === 0) return ['0', 0];
  const [mantissa, exponent] = x.toExponential().split('e');
  return [mantissa.replace('.', ''), Number(exponent)];
}

/**
 * repr() of a float. CPython prints the shortest round-tripping decimal and only
 * switches to scientific notation when the decimal point lands at position <= -4
 * or > 16 (so 1e15 prints in full but 1e16 does not). Exponents carry a sign and
 * at least two digits.
 */
export function reprFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const negative = x < 0 || Object.is(x, -0);
  const [digits, exponent] = shortestDigits(Math.abs(x));
  const decpt = exponent + 1;

  let body;
  if (decpt <= -4 || decpt > 16) {
    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const exp = decpt - 1;
    body = `${mantissa}e${exp < 0 ? '-' : '+'}${String(Math.abs(exp)).padStart(2, '0')}`;
  } else if (decpt <= 0) {
    body = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    body = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }
  return negative ? `-${body}` : body;
}

export function pyRepr(value) {
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return reprFloat(value);
  if (typeof value === 'string') return reprStr(value);
  if (value instanceof PyTuple) {
    const items = value.items.map(pyRepr);
    return items.length === 1 ? `(${items[0]},)` : `(${items.join(', ')})`;
  }
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  throw new TypeError(`no Python repr for ${typeof value}`);
}

/** `print(value)`: str() semantics, which differ from repr() only for strings. */
export function pyPrint(value) {
  console.log(typeof value === 'string' ? value : pyRepr(value));
}

