import { writeFileSync } from 'node:fs';

const cases = [];
const add = (argv) => { cases.push(argv); };

// ---------- helpers: bash quoting (ASCII-safe output; raw bytes via $'\xNN') ----------
const RAW = Symbol('raw'); // marker: token already bash-quoted verbatim
const raw = (s) => ({ [RAW]: s });

function bq(tok) {
  if (typeof tok === 'object' && tok !== null && tok[RAW] !== undefined) return tok[RAW];
  const s = String(tok);
  if (s === '') return "''";
  // any char < 0x20 or 0x7f -> use $'...'
  if ([...s].some((c) => { const v = c.codePointAt(0); return v < 0x20 || v === 0x7f; })) {
    let o = "$'";
    for (const c of s) {
      const v = c.codePointAt(0);
      if (c === '\\') o += '\\\\';
      else if (c === "'") o += "\\'";
      else if (v < 0x20 || v === 0x7f) o += '\\x' + v.toString(16).padStart(2, '0');
      else o += c;
    }
    return o + "'";
  }
  return "'" + s.replace(/'/g, `'\\''`) + "'";
}

const NAMES = ['a', 'b', 'c', 'd', 'e'];
const OK = { a: '1', b: '2', c: '3', d: '4', e: '5' };
const full = () => NAMES.flatMap((n) => [`--${n}`, OK[n]]);
// full arg list with one option replaced by given tokens
const withOpt = (name, tokens) => NAMES.flatMap((n) => (n === name ? tokens : [`--${n}`, OK[n]]));
// full list minus one option
const without = (name) => NAMES.filter((n) => n !== name).flatMap((n) => [`--${n}`, OK[n]]);

// ---------- A. baseline / ordering ----------
add([]);
add(full());
let rng = 1234567;
const rand = () => (rng = (rng * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
for (let k = 0; k < 18; k++) {
  const order = [...NAMES];
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const mixEq = k % 3;
  add(order.flatMap((n, i) => (mixEq === 0 || (mixEq === 1 && i % 2 === 0) ? [`--${n}`, OK[n]] : [`--${n}=${OK[n]}`])));
}

// ---------- B. missing / duplicated / misspelled ----------
for (const n of NAMES) add(without(n));
for (let i = 0; i < NAMES.length; i++) for (let j = i + 1; j < NAMES.length; j++) {
  add(NAMES.filter((n) => n !== NAMES[i] && n !== NAMES[j]).flatMap((n) => [`--${n}`, OK[n]]));
}
for (const n of NAMES) add([...full(), `--${n}`, '99']);            // duplicate at end
for (const n of NAMES) add([`--${n}`, '99', ...full()]);            // duplicate at front
for (const n of NAMES) add([...full(), `--${n}=99`]);
for (const bad of ['--aa', '--A', '--a1', '-a', '--ab', '--abc', '--f', '--ee', '--_a', '--a_', '--a-']) {
  add(withOpt('a', [bad, '1']));
}
// misspelled *added* on top of a complete valid set
for (const bad of ['--z', '-z', '--zz', '-1x', '--1', '-.', '--.']) add([...full(), bad, '7']);

// ---------- C. '=' forms with weird values ----------
for (const v of ['', '=1', '+1', ' 1', '1 ', '-0', '-', '--', '=', '-1', '0x1', '1e2', 'inf', 'nan',
                 '1_0', '_1', '1_', '1__0', '+_1', '007', '  -7  ', '1 2', "1'2", '1"2', '-1.5',
                 '١٢', '１２', '१२', '۱۲', '๑๒',
                 '1٢', '12345678901234567890123456789012345', '-12345678901234567890123456789012345',
                 ' 7 ', '​7', '　1　', '1 2', '+0', '-000', '0']) {
  add(withOpt('a', [`--a=${v}`]));
}
add(withOpt('a', [raw(`'--a='$'\\t''7'$'\\n'`)]));   // --a=<TAB>7<NL>
add(withOpt('a', [raw(`'--a='$'\\n'`)]));
add(withOpt('a', [raw(`'--a=1'$'\\n'`)]));

// ---------- D. abbreviation / dash space ----------
for (const t of ['--h', '--he', '--hel', '--help', '--hell', '--helpx', '-h', '-hh', '-hhh', '-hx',
                 '-h=1', '-h=', '--help=x', '--help=', '--help=1', '--h=1', '--he=1', '--', '---', '-',
                 '----a', '--=1', '--=', '-=', '-=1', '--a-', '-ha', '-ah', '--HELP', '-H']) {
  add([t]);
  add([t, ...full()]);
  add([...full(), t]);
}
add(['----a', '1', ...without('a')]);
add(['---a', '1', ...without('a')]);
add(['--a-', '1', ...without('a')]);

// ---------- E. values that look like options ----------
for (const v of ['-1', '-1.5', '-.5', '-x', '--', '-', '-1 ', ' -1', '-0', '-1e2', '-12345678901234567890123456789012',
                 '-١٢', '-1.', '--1', '-1_0', '-', '- 1', '-١.٢']) {
  add(withOpt('a', ['--a', v]));
